SELECT * FROM memorial
WHERE user_id = #{userId} AND type = #{type}
ORDER BY date ASC

SELECT * FROM memorial
WHERE user_id = #{userId} AND type != #{type}
ORDER BY date ASC

SELECT * FROM memorial
WHERE user_id = #{userId} AND date >= #{startDate} AND date <= #{endDate}
ORDER BY date ASC

SELECT * FROM memorial
WHERE user_id = #{userId} AND MONTH(date) = #{month}
ORDER BY DAY(date) ASC
